"""Functions for calculating cash payment handling for the till."""

from shopkit.pos.cash import round_up_to_next_dollar, round_to_nearest_dollar, truncate_to_dollar


def amount_due(total_cents: int, currency: str, paid_by: str) -> int:
    """Calculate the amount a customer is asked to pay based on payment method and currency rules.

    Args:
        total_cents: The total amount in cents
        currency: The currency code (e.g., "CAD", "USD", "EUR")
        paid_by: The payment method ("card" or "cash")

    Returns:
        The amount to be paid in cents

    Raises:
        ValueError: If paid_by is not "card" or "cash"
    """
    if paid_by not in ("card", "cash"):
        raise ValueError(f"paid_by must be 'card' or 'cash', got {paid_by!r}")

    if paid_by == "card":
        return total_cents

    if currency == "CAD":
        # Cash payments in CAD are always truncated down to the nearest dollar
        return truncate_to_dollar(total_cents)
    elif currency == "USD":
        # Cash payments in USD are rounded to the nearest dollar
        return round_to_nearest_dollar(total_cents)
    elif currency == "EUR":
        # Cash payments in EUR are rounded up to the next dollar
        return round_up_to_next_dollar(total_cents)
    else:
        # For other currencies, use the default rounding to nearest dollar
        return round_to_nearest_dollar(total_cents)
